select case when year(sale_date) < 2024 then 'before_2024' when year(sale_date) = 2024 then '2024' else 'after_2024' end as sale_cohort, count(revenue) as revenue_count, count(*) as cnt, round(stddev(units), 2) as stddev_units from store_sales where units <= 12 or store_id = 1 group by case when year(sale_date) < 2024 then 'before_2024' when year(sale_date) = 2024 then '2024' else 'after_2024' end order by cnt desc;
